import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Claim, Claims } from './claims';
import { Session, isDate } from './session';

/** A person's plan: a DRAFT claim of its amount on every plan date (the start, then every so many days; or
 *  monthly on a day of the month) up to its end, and how many claims it has made so far. */
export interface Plan {
  id: number;
  personId: number;
  amount: string;
  start: string;
  /** Every so many days; null for a monthly plan. */
  every: number | null;
  /** The day of the month (1 to 31) of a monthly plan; null for one run every so many days. */
  day: number | null;
  end: string;
  generated: number;
}

/** A plan's fields as typed. */
export interface PlanFields {
  amount: string;
  start: string;
  every: string;
  day: string;
  end: string;
}

// The active sheet's plans, in the order they were added, re-read from the server each time the sheet is
// loaded.
@Injectable({ providedIn: 'root' })
export class Plans {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);
  private readonly claims = inject(Claims);

  readonly plans = signal<Plan[]>([]);
  private loads = 0;

  /** Re-read the active sheet's plans from the server; an error message when that failed. */
  async load(): Promise<string | null> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    const load = ++this.loads;
    this.plans.set([]);
    if (!user || !sid) return null;
    try {
      const plans = await firstValueFrom(this.http.get<Plan[]>(this.url(sid), { headers: { 'X-User': user } }));
      if (load === this.loads) this.plans.set(plans);
      return null;
    } catch (e) {
      return e instanceof HttpErrorResponse ? `Could not load plans (${e.status}).` : 'Could not load plans.';
    }
  }

  /** Add a plan to a person, run every so many days or, with a day of the month typed, monthly on that day;
   *  an error message when refused (a bad amount, interval or day, or an end before the start). */
  async add(personId: number, f: PlanFields): Promise<string | null> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    if (!user || !sid) return 'Load a sheet first.';
    const amount = f.amount.trim();
    const start = f.start.trim() || (this.session.today() ?? '');
    const every = f.every.trim();
    const day = f.day.trim();
    const end = f.end.trim();
    if (!/^\d+(\.\d{1,2})?$/.test(amount)) return 'Enter an amount of 0.00 or more with up to two decimals.';
    if (!isDate(start)) return 'Enter a start date as YYYY-MM-DD.';
    if (day) {
      if (every) return 'Enter either every how many days or a day of the month, not both.';
      if (!/^\d+$/.test(day) || Number(day) < 1 || Number(day) > 31) return 'Enter a day of the month from 1 to 31.';
    } else if (!/^\d+$/.test(every) || Number(every) < 1) return 'Enter every how many days, 1 or more.';
    if (!isDate(end)) return 'Enter an end date as YYYY-MM-DD.';
    if (end < start) return 'The end cannot be before the start.';
    try {
      const plan = await firstValueFrom(
        this.http.post<Plan>(
          `/api/sheets/${encodeURIComponent(sid)}/people/${personId}/plans`,
          day ? { amount, start, day: Number(day), end } : { amount, start, every: Number(every), end },
          { headers: { 'X-User': user } },
        ),
      );
      if (this.session.sheetId() === sid) this.plans.update((ps) => [...ps, plan]);
      return null;
    } catch (e) {
      return failed('add plan', e);
    }
  }

  /** Make the plans' claims due by the sheet's today: how many were made, or an error message when refused. */
  async generate(): Promise<number | string> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    if (!user || !sid) return 'Load a sheet first.';
    try {
      const done = await firstValueFrom(
        this.http.post<{ made: number; claims: Claim[]; plans: Plan[] }>(
          `${this.url(sid)}/generate`,
          {},
          { headers: { 'X-User': user } },
        ),
      );
      if (this.session.sheetId() === sid) {
        this.claims.claims.update((cs) => [...[...done.claims].reverse(), ...cs]);
        this.plans.set(done.plans);
      }
      return done.made;
    } catch (e) {
      return failed('generate plans', e);
    }
  }

  private url(sid: string): string {
    return `/api/sheets/${encodeURIComponent(sid)}/plans`;
  }
}

function failed(what: string, e: unknown): string {
  if (e instanceof HttpErrorResponse) {
    const err: unknown = e.error;
    if (err && typeof err === 'object' && 'message' in err && typeof err.message === 'string' && err.message) {
      return err.message;
    }
    if (e.status === 400) return 'Enter an amount with up to two decimals, dates as YYYY-MM-DD and every 1 or more days.';
    return `Could not ${what} (${e.status}).`;
  }
  return `Could not ${what}.`;
}
import { Component, computed, inject, input, signal } from '@angular/core';
import { Plans } from '../../core/plans';

// A person's plans, each with how many claims it has made so far, and a form adding one, run every so many days
// or monthly on a day of the month (a bad amount, interval or day, or an end before the start, is refused with
// an error on the row).
@Component({
  selector: 'app-person-plans',
  template: `
    <ul aria-label="Plans">
      @for (pl of mine(); track pl.id) {
        <li [attr.data-testid]="'plan-row-' + pl.id">
          <span data-testid="plan-amount-shown">{{ pl.amount }}</span>
          from <span data-testid="plan-start">{{ pl.start }}</span>
          @if (pl.day !== null) {
            monthly on day <span data-testid="plan-day">{{ pl.day }}</span>
          } @else {
            every <span data-testid="plan-every">{{ pl.every }}</span> days
          }
          to <span data-testid="plan-end">{{ pl.end }}</span>,
          made <span data-testid="plan-generated">{{ pl.generated }}</span>
        </li>
      }
    </ul>
    <form (submit)="add($event)" [attr.aria-label]="'Add a plan for ' + personName()">
      <label [for]="'plan-form-amount-' + personId()">Plan amount</label>
      <input
        [id]="'plan-form-amount-' + personId()"
        data-testid="plan-form-amount"
        inputmode="decimal"
        [value]="amount()"
        (input)="amount.set(value($event)); error.set(null)"
      />
      <label [for]="'plan-form-start-' + personId()">Start</label>
      <input
        [id]="'plan-form-start-' + personId()"
        data-testid="plan-form-start"
        placeholder="YYYY-MM-DD"
        [value]="start()"
        (input)="start.set(value($event)); error.set(null)"
      />
      <label [for]="'plan-form-every-' + personId()">Every (days)</label>
      <input
        [id]="'plan-form-every-' + personId()"
        data-testid="plan-form-every"
        inputmode="numeric"
        [value]="every()"
        (input)="every.set(value($event)); error.set(null)"
      />
      <label [for]="'plan-form-day-' + personId()">Or monthly on day (1 to 31)</label>
      <input
        [id]="'plan-form-day-' + personId()"
        data-testid="plan-form-day"
        inputmode="numeric"
        [value]="day()"
        (input)="day.set(value($event)); error.set(null)"
      />
      <label [for]="'plan-form-end-' + personId()">End</label>
      <input
        [id]="'plan-form-end-' + personId()"
        data-testid="plan-form-end"
        placeholder="YYYY-MM-DD"
        [value]="end()"
        (input)="end.set(value($event)); error.set(null)"
      />
      <button type="submit" data-testid="plan-form-submit" [disabled]="saving()">
        Add plan<span class="visually-hidden"> for {{ personName() }}</span>
      </button>
      @if (error(); as err) {
        <p role="alert" data-testid="plan-error">{{ err }}</p>
      }
    </form>
  `,
})
export class PersonPlans {
  protected readonly plans = inject(Plans);
  readonly personId = input.required<number>();
  readonly personName = input.required<string>();
  protected readonly mine = computed(() => this.plans.plans().filter((p) => p.personId === this.personId()));
  protected readonly amount = signal('');
  protected readonly start = signal('');
  protected readonly every = signal('');
  protected readonly day = signal('');
  protected readonly end = signal('');
  protected readonly error = signal<string | null>(null);
  protected readonly saving = signal(false);

  protected value(e: Event): string {
    return (e.target as HTMLInputElement).value;
  }

  protected async add(e: Event): Promise<void> {
    e.preventDefault();
    if (this.saving()) return; // a second submit before the first has answered
    this.error.set(null);
    this.saving.set(true);
    try {
      const err = await this.plans.add(this.personId(), {
        amount: this.amount(),
        start: this.start(),
        every: this.every(),
        day: this.day(),
        end: this.end(),
      });
      if (err) this.error.set(err);
      else {
        this.amount.set('');
        this.start.set('');
        this.every.set('');
